// fishmeta: Intercontinental Fish's core meta as small learned policies. The weights live in fish_meta_params.h,
// generated by analysis/fish_bc/fit_meta.py from Fish's own games; nothing here is tuned by hand. Feature
// definitions (order, scaling, vision rules) must match fit_meta.py exactly. Included into bot.cpp (namespace mm).
#include "fish_meta_params.h"

namespace fm {
struct Unit {
    unsigned id = 0;
    int type = -1, range = 1, cd0 = -1, cd1 = -1;
    vec2 p{0, 0};
    float hp = 0, mhp = 1;
    unsigned state = 0, gems = 0;
    int d = 99;
};
struct View {
    unsigned selfId = 0;
    vec2 pos{0, 0};
    float hp = 0, mhp = 1;
    int range = 1, cd0 = -1, cd1 = -1;
    unsigned gems = 0, gold = 0;
    std::vector<Unit> allies, enemies;
    int nearest = -1, nearestD = 99;
    bool campAdjacent = false;
};
static constexpr bool rangedType(int t) { return t == 1 || t == 3 || t == 5 || t == 6 || t == 8 || t == 11; }
static float dot(const float* w, const float* x, int n) { float s = 0; for (int i = 0; i < n; ++i) s += w[i] * x[i]; return s; }
}  // namespace fm

// Everything one champion sees this turn, as in the training data (own vision only, live champions only).
static bool fmView(fm::View& v) {
    namespace sd = bc::detail;
    auto& me = bc::self();
    v.selfId = static_cast<unsigned>(static_cast<bc::handle_champion_t>(me));
    sd::champion_info si{};
    if (sd::sdk_champion(v.selfId, &si)) return false;
    v.pos = {si.x, si.y}; v.hp = si.health; v.mhp = std::max(1.0f, si.max_health); v.range = si.attack_range;
    sd::sdk_champion_gems(v.selfId, &v.gems); sd::sdk_champion_gold(v.selfId, &v.gold);
    sd::sdk_champion_cooldown(v.selfId, 0, &v.cd0); sd::sdk_champion_cooldown(v.selfId, 1, &v.cd1);
    for (auto p : bc::vision::champion_tiles().positions()) {
        if (!enough(22000)) return false;
        unsigned id = 0; sd::champion_info ci{};
        if (sd::sdk_champion_at(p.x, p.y, &id) || id == v.selfId || sd::sdk_champion(id, &ci) || !(ci.state & 1)) continue;
        fm::Unit u; u.id = id; u.type = ci.type; u.range = ci.attack_range; u.p = {ci.x, ci.y};
        u.hp = ci.health; u.mhp = std::max(1.0f, ci.max_health); u.state = ci.state; u.d = cheb(u.p, v.pos);
        if (ci.team == si.team) { v.allies.push_back(u); continue; }
        sd::sdk_champion_gems(id, &u.gems); sd::sdk_champion_cooldown(id, 0, &u.cd0); sd::sdk_champion_cooldown(id, 1, &u.cd1);
        if (u.d < v.nearestD) { v.nearestD = u.d; v.nearest = static_cast<int>(v.enemies.size()); }
        v.enemies.push_back(u);
    }
    for (auto p : bc::vision::camp_tiles().positions()) {
        if (cheb(p, v.pos) > 1) continue;
        unsigned id = 0; std::uint32_t st = 0;
        if (!sd::sdk_camp_at(p.x, p.y, &id) && !sd::sdk_camp_state(id, &st) && st == 1) { v.campAdjacent = true; break; }
    }
    return true;
}

// fit_meta.py MOVE_FEATURES
static void fmMoveFeatures(const fm::View& v, float* x) {
    const float own = v.hp / v.mhp;
    const fm::Unit& e = v.enemies[v.nearest];
    const float ehp = e.hp / e.mhp;
    int a4 = 0, e4 = 0; float power = own;
    for (auto& a : v.allies) if (a.d <= 4) { ++a4; power += a.hp / a.mhp; }
    for (auto& o : v.enemies) if (o.d <= 4) { ++e4; power -= o.hp / o.mhp; }
    const int d = v.nearestD;
    const bool ownRanged = v.range > 1;
    auto b = [](bool c) { return c ? 1.0f : 0.0f; };
    const float f[fishmeta::MOVE_NF] = {1.0f, own, b(own < 0.25f), b(own < 0.4f), b(own < 0.6f), ehp, b(ehp < 0.2f), b(ehp < 0.3f),
        b(ehp < 0.5f), v.gems / 50.0f, static_cast<float>(a4 + 1 - e4), power, b(d == 1), b(d == 2), b(d == 3), b(d == 4),
        std::min(d, 5) / 5.0f, b(fm::rangedType(e.type)), b(ownRanged), b(!ownRanged && d == 2), b(ownRanged && d <= 3),
        b(e.cd0 == 0 || e.cd1 == 0), b(e.state & 6), b(v.cd0 == 0), b(v.cd1 == 0), v.allies.size() / 4.0f, b(v.campAdjacent)};
    std::copy(f, f + fishmeta::MOVE_NF, x);
}

// 0 stay, 1 approach, 2 retreat, 3 sidestep (relative to the nearest visible enemy)
static int fmMoveClass(const fm::View& v) {
    float x[fishmeta::MOVE_NF];
    fmMoveFeatures(v, x);
    int best = 0; float bs = -1e30f;
    for (int c = 0; c < fishmeta::MOVE_NC; ++c) {
        const float s = fm::dot(fishmeta::MOVE_W[c], x, fishmeta::MOVE_NF);
        if (s > bs) { bs = s; best = fishmeta::MOVE_CLASS[c]; }
    }
    return best;
}

// fit_meta.py RECALL_FEATURES. Fish recalls with a per-turn hazard (e.g. ~10% of turns at 20-30% HP), so the learned
// probability is used as that hazard: one seeded draw per turn.
static bool fmWantsRecall(const fm::View& v, float spawnCx, float spawnCy) {
    const float own = v.hp / v.mhp;
    int e4 = 0; for (auto& o : v.enemies) if (o.d <= 4) ++e4;
    const int d = v.nearestD <= 7 ? v.nearestD : 99;
    const float spawnD = std::max(std::abs(spawnCx - v.pos.x), std::abs(spawnCy - v.pos.y));
    auto b = [](bool c) { return c ? 1.0f : 0.0f; };
    const float x[fishmeta::RECALL_NF] = {1.0f, own, b(own < 0.3f), b(own < 0.4f), b(own < 0.5f), b(own < 0.6f), v.gems / 50.0f,
        std::min<float>(v.gold, 500) / 100.0f, b(v.gold >= 120), b(v.gold >= 180), b(d <= 8), std::min(d, 9) / 9.0f,
        static_cast<float>(e4), spawnD / 40.0f, b(v.campAdjacent)};
    const float p = 1.0f / (1.0f + std::exp(-fm::dot(fishmeta::RECALL_W, x, fishmeta::RECALL_NF)));
    return random_number(1000000) < static_cast<unsigned>(p * 1000000.0f);
}

// Learned target score (fit_meta.py TARGET_FEATURES) among the enemies the attack can reach from `from`.
static int fmPickTarget(const fm::View& v, vec2 from, int range) {
    int best = -1; float bs = -1e30f;
    for (int i = 0; i < static_cast<int>(v.enemies.size()); ++i) {
        const auto& e = v.enemies[i];
        const int d = cheb(e.p, from);
        if (d > range) continue;
        const float x[fishmeta::TARGET_NF] = {e.hp / 1000.0f, e.hp / e.mhp, static_cast<float>(d), (e.state & 6) ? 1.0f : 0.0f,
            e.gems / 50.0f, fm::rangedType(e.type) ? 1.0f : 0.0f};
        const float s = fm::dot(fishmeta::TARGET_W, x, fishmeta::TARGET_NF);
        if (s > bs) { bs = s; best = i; }
    }
    return best;
}

static std::optional<bc::champion> fmChampion(unsigned id) {
    for (auto& e : safeChamps(team::enemy)) if (static_cast<unsigned>(static_cast<bc::handle_champion_t>(e)) == id) return e;
    return std::nullopt;
}

// Hit the learned target in range (abilities in v62's per-kit order). Returns true when a basic attack landed.
bool Bot::fmStrike(const fm::View& v) {
    auto& me = bc::self();
    if (attackedThisTurn || !enough(26000)) return false;
    const int i = fmPickTarget(v, me.position(), me.attack_range());
    if (i < 0) return false;
    auto tgt = fmChampion(v.enemies[i].id);
    if (!tgt || !v60SafeOptionalHit(*tgt)) return false;
    if (myType == bc::champion_type::cassi || myType == bc::champion_type::ren) castOnEnemy(*tgt);
    if (!me.can_attack()) { castOnEnemy(*tgt); return false; }
    try { if (tgt->is_visible() && tgt->is_alive() && ACT(me.attack(*tgt))) attackedThisTurn = true; } catch (const TurnAbort&) { throw; } catch (...) {}
    if (!attackedThisTurn) return false;
    afterAttackReset(&*tgt);
    if (!castThisTurn) { if (myType == bc::champion_type::varg) { if (useShield()) castThisTurn = true; } else castOnEnemy(*tgt); }
    stage = "fm-strike";
    return true;
}

// Keep the distance to the nearest enemy, preferring tiles near allies and away from the other enemies.
bool Bot::fmSidestep(const fm::View& v) {
    auto& me = bc::self();
    if (!me.can_move() || movedThisTurn || !enough(30000)) return false;
    const vec2 pos = me.position(), foe = v.enemies[v.nearest].p;
    const int keep = cheb(pos, foe);
    auto score = [&](vec2 t) {
        int s = 0;
        for (auto& e : v.enemies) s -= 2 * std::max(0, 5 - cheb(t, e.p));
        for (auto& a : v.allies) s += std::max(0, 4 - cheb(t, a.p));
        return s;
    };
    vec2 best = pos; int bs = score(pos);
    for (auto t : blockedNow().reachable_tiles(pos, 1).positions()) {
        if (t == pos || cheb(t, foe) != keep) continue;
        const int s = score(t);
        if (s > bs) { bs = s; best = t; }
    }
    if (best == pos) return false;
    try { if (ACT(me.move_absolute(best))) { previousTile = pos; movedThisTurn = true; stage = "fm-sidestep"; return true; } } catch (const TurnAbort&) { throw; } catch (...) {}
    return false;
}

// The turn when an enemy is within 5 tiles. Fish acts before it moves when a target is already in reach (melee champions
// may hit and still step; ranged ones choose one of the two, as the rules require).
bool Bot::fmFight() {
    if (!FM_FIGHT || !enough(40000)) return false;
    auto& me = bc::self();
    fm::View v;
    if (!fmView(v) || v.nearest < 0 || v.nearestD > 5) return false;
    progressKind = combat;
    // Recall is cancelled by any damage: only start it out of every visible enemy's reach (its range plus one step).
    if (FM_RECALL && !me.is_recalling() && !onSpawn()) {
        bool reachable = false;
        for (auto& e : v.enemies) reachable |= e.d <= e.range + 1;
        if (!reachable && fmWantsRecall(v, spawnCx, spawnCy)) {
            try { if (ACT(me.recall())) { releaseCapture(); stage = "fm-recall-fight"; return true; } } catch (const TurnAbort&) { throw; } catch (...) {}
        }
    }
    const int cls = fmMoveClass(v);
    const bool melee = me.attack_range() <= 1;
    // A ranged champion that wants to reposition does not shoot (shooting would spend its move).
    if (melee || cls == 0 || cls == 1) fmStrike(v);
    if (!ranged || !attackedThisTurn) {
        if (cls == 1 && !movedThisTurn && me.can_move()) {
            bc::bitboard goals;
            goals.draw_chebyshev(v.enemies[v.nearest].p, std::max(1, static_cast<int>(me.attack_range())));
            if (moveToward(goals, v.nearestD >= 3)) stage = "fm-approach";
        } else if (cls == 2 && !movedThisTurn) {
            std::vector<vec2> threats;
            for (auto& e : v.enemies) if (e.d <= 7) threats.push_back(e.p);
            if (moveAway(threats)) stage = "fm-retreat";
        } else if (cls == 3) fmSidestep(v);
        else if (cls == 0) stage = "fm-hold";
    }
    // Moved into reach: strike now (a melee step-in, or the target walked into range).
    if (!attackedThisTurn && (melee || !movedThisTurn) && enough(30000)) {
        fm::View after;
        if (fmView(after) && after.nearest >= 0) fmStrike(after);
    }
    return true;
}

// Outside fights: Fish's recall decision (heal, shop, carry home). Any damage cancels a recall, so when an enemy or an
// awake camp could reach this tile the champion first walks out of reach and recalls on a later turn.
bool Bot::fmRecall() {
    if (!FM_RECALL || onSpawn() || !enough(40000)) return false;
    auto& me = bc::self();
    if (me.is_recalling()) return true;
    fm::View v;
    if (!fmView(v) || !fmWantsRecall(v, spawnCx, spawnCy)) return false;
    std::vector<vec2> threats;
    for (auto& e : v.enemies) if (e.d <= e.range + 1) threats.push_back(e.p);
    for (auto tile : bc::vision::camp_tiles().positions()) {
        const int r = campRanges[idx(tile)];
        if (r == 0 || cheb(tile, v.pos) > r) continue;
        unsigned id = 0; std::uint32_t st = 0;
        if (!bc::detail::sdk_camp_at(tile.x, tile.y, &id) && !bc::detail::sdk_camp_state(id, &st) && st == 1) threats.push_back(tile);
    }
    releaseCapture();
    if (!threats.empty()) {
        if (moveAway(threats)) { stage = "fm-recall-walk"; return true; }
        return false;
    }
    try { if (ACT(me.recall())) { stage = "fm-recall"; return true; } } catch (const TurnAbort&) { throw; } catch (...) {}
    return false;
}
